    }
    case 'confirm1':
    case 'confirm2': {
      const call = step === 'confirm1' ? 1 : 2;
      const ev = res.body || {};
      const link = ev.hangoutLink || ((((ev.conferenceData || {}).entryPoints) || []).find((x) => x.entryPointType === 'video') || {}).uri;
      if (call === 1) Object.assign(fields, { 'Payment status': 'Captured' });
