    case 'slots2': mail(slotsEmail(rec, ctx.slots, 2, S)); Object.assign(fields, { 'Call 2 slots emailed at': now, 'Status': 'Call 2 offered' }); log = 'Call 2 times emailed: ' + ctx.slots.map((s) => s.label).join(' | '); break;
