          'Marketing consent': true, 'Nurture status': 'Active', 'Nurture step': 0, 'Signed up at': now, 'Unsubscribe token': randomToken(32), 'Audit offer': '£100', 'Revenue band': sel(fv(rec, 'Revenue band')) || undefined } }] } }));
